package trevor.tobhealthbars;

import java.util.concurrent.atomic.AtomicBoolean;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class PartyOrbWidgetsTest
{
	private final Client client = mock(Client.class);
	private final PartyOrbWidgets widgets = new PartyOrbWidgets(client);
	private Widget status;
	private Widget orb;
	private Widget spectator;
	private Widget exit;

	@Before
	public void setUp()
	{
		status = widget(InterfaceID.TobHud.STATUS_CONTAINER, -1);
		orb = widget(InterfaceID.TobHud._0_CONTAINER, -1);
		spectator = widget(InterfaceID.TobHud.SPECTATOR_CONTAINER, -1);
		exit = widget(InterfaceID.TobHud.SPECTATOR_EXIT, -1);
		status.setOriginalWidth(34);
		status.setOriginalHeight(209);
		spectator.setOriginalWidth(34);
		spectator.setOriginalHeight(34);
		spectator.setOriginalY(175);
		spectator.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
		when(spectator.getStaticChildren()).thenReturn(new Widget[]{exit});
	}

	@Test
	public void spectatorHudReservesOnlyExitOrbSpaceAndRestoresItsLayout()
	{
		widgets.hideOrbs();
		widgets.hideOrbs();
		assertEquals(34, status.getOriginalWidth());
		assertEquals(34, status.getOriginalHeight());
		assertEquals(0, spectator.getOriginalX());
		assertEquals(0, spectator.getOriginalY());
		assertEquals(WidgetPositionMode.ABSOLUTE_TOP, spectator.getYPositionMode());
		assertFalse(spectator.isHidden());
		verify(status, org.mockito.Mockito.atLeastOnce()).revalidateScroll();

		widgets.restore();
		assertEquals(34, status.getOriginalWidth());
		assertEquals(209, status.getOriginalHeight());
		assertEquals(175, spectator.getOriginalY());
		assertEquals(WidgetPositionMode.ABSOLUTE_CENTER, spectator.getXPositionMode());
	}

	@Test
	public void participantHudReservesNoSpaceAndExpandsOnlyForExit()
	{
		spectator.setHidden(true);
		status.setOriginalHeight(174);
		widgets.hideOrbs();
		assertEquals(0, status.getOriginalWidth());
		assertEquals(0, status.getOriginalHeight());
		assertTrue(widgets.isHudVisible());

		widgets.restoreLayout();
		assertEquals(174, status.getOriginalHeight());
		status.setOriginalHeight(209);
		spectator.setHidden(false);
		widgets.hideOrbs();
		assertEquals(34, status.getOriginalHeight());
		widgets.restore();
		assertEquals(209, status.getOriginalHeight());
	}

	@Test
	public void layoutRefreshKeepsNewNativeDimensionsForShutdown()
	{
		widgets.hideOrbs();
		widgets.restoreLayout();

		status.setOriginalWidth(40);
		status.setOriginalHeight(215);
		status.setWidthMode(WidgetSizeMode.MINUS);
		spectator.setOriginalY(3);
		spectator.setYPositionMode(WidgetPositionMode.ABSOLUTE_BOTTOM);
		widgets.hideOrbs();
		assertEquals(WidgetSizeMode.ABSOLUTE, status.getWidthMode());
		assertEquals(34, status.getOriginalHeight());
		widgets.restore();
		assertEquals(40, status.getOriginalWidth());
		assertEquals(215, status.getOriginalHeight());
		assertEquals(WidgetSizeMode.MINUS, status.getWidthMode());
		assertEquals(3, spectator.getOriginalY());
		assertEquals(WidgetPositionMode.ABSOLUTE_BOTTOM, spectator.getYPositionMode());
	}

	@Test
	public void missingExitContainerStillRemovesBlankPartySpace()
	{
		when(client.getWidget(InterfaceID.TobHud.SPECTATOR_CONTAINER)).thenReturn(null);
		widgets.hideOrbs();
		assertEquals(0, status.getOriginalWidth());
		assertEquals(0, status.getOriginalHeight());
		widgets.restore();
		assertEquals(209, status.getOriginalHeight());
	}

	@Test
	public void hidesOnlyOrbsAndRestoresOriginalVisibility()
	{
		Widget initiallyHidden = widget(InterfaceID.TobHud._1_CONTAINER, -1);
		initiallyHidden.setHidden(true);
		widgets.hideOrbs();
		widgets.hideOrbs();
		assertTrue(orb.isSelfHidden());
		verify(status, never()).setHidden(anyBoolean());
		verify(spectator, never()).setHidden(anyBoolean());
		verify(exit, never()).setHidden(anyBoolean());
		widgets.restore();
		assertFalse(orb.isSelfHidden());
		assertTrue(initiallyHidden.isSelfHidden());
	}

	@Test
	public void hiddenOrMissingHudDoesNotHideOrbs()
	{
		status.setHidden(true);
		widgets.hideOrbs();
		assertFalse(orb.isSelfHidden());
		when(client.getWidget(InterfaceID.TobHud.STATUS_CONTAINER)).thenReturn(null);
		widgets.hideOrbs();
		assertFalse(orb.isSelfHidden());
	}

	@Test
	public void rebuiltHudRestoresOldWidgetsAndHidesNewOrbs()
	{
		widgets.hideOrbs();
		widget(InterfaceID.TobHud.STATUS_CONTAINER, -1);
		Widget replacement = widget(InterfaceID.TobHud._0_CONTAINER, -1);
		widgets.hideOrbs();
		assertFalse(orb.isSelfHidden());
		assertTrue(replacement.isSelfHidden());
		widgets.restore();
		assertFalse(replacement.isSelfHidden());
	}

	private Widget widget(int id, int index)
	{
		Widget widget = mock(Widget.class);
		AtomicBoolean hidden = new AtomicBoolean();
		when(widget.getId()).thenReturn(id);
		when(widget.getIndex()).thenReturn(index);
		when(widget.getItemId()).thenReturn(-1);
		when(widget.getWidth()).thenAnswer(invocation -> widget.getOriginalWidth());
		when(widget.getHeight()).thenAnswer(invocation -> widget.getOriginalHeight());
		doAnswer(call -> { when(widget.getOriginalWidth()).thenReturn(call.getArgument(0)); return widget; }).when(widget).setOriginalWidth(anyInt());
		doAnswer(call -> { when(widget.getOriginalHeight()).thenReturn(call.getArgument(0)); return widget; }).when(widget).setOriginalHeight(anyInt());
		doAnswer(call -> { when(widget.getWidthMode()).thenReturn(call.getArgument(0)); return widget; }).when(widget).setWidthMode(anyInt());
		doAnswer(call -> { when(widget.getHeightMode()).thenReturn(call.getArgument(0)); return widget; }).when(widget).setHeightMode(anyInt());
		doAnswer(call -> { when(widget.getOriginalX()).thenReturn(call.getArgument(0)); return widget; }).when(widget).setOriginalX(anyInt());
		doAnswer(call -> { when(widget.getOriginalY()).thenReturn(call.getArgument(0)); return widget; }).when(widget).setOriginalY(anyInt());
		doAnswer(call -> { when(widget.getXPositionMode()).thenReturn(call.getArgument(0)); return widget; }).when(widget).setXPositionMode(anyInt());
		doAnswer(call -> { when(widget.getYPositionMode()).thenReturn(call.getArgument(0)); return widget; }).when(widget).setYPositionMode(anyInt());
		when(widget.isSelfHidden()).thenAnswer(invocation -> hidden.get());
		when(widget.isHidden()).thenAnswer(invocation -> hidden.get());
		doAnswer(invocation -> { hidden.set(invocation.getArgument(0)); return null; }).when(widget).setHidden(anyBoolean());
		when(client.getWidget(id)).thenReturn(widget);
		return widget;
	}
}

package trevor.tobhealthbars;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class TobHealthBarsOverlayTest
{
	private final Client client = mock(Client.class);
	private final TobHealthBarsPlugin plugin = mock(TobHealthBarsPlugin.class);
	private final TobHealthBarsConfig config = new TobHealthBarsConfig()
	{
		@Override
		public boolean showLocalName()
		{
			return false;
		}

		@Override
		public Color dawnbringerColor()
		{
			return Color.MAGENTA;
		}
	};
	private final TobHealthBarsOverlay overlay = new TobHealthBarsOverlay(client, plugin, config);

	@Test
	public void highlightsByRealNameEvenWhenLocalLabelIsMe()
	{
		when(plugin.shouldRender()).thenReturn(true);
		when(client.getVarbitValue(VarbitID.TOB_CLIENT_P0)).thenReturn(27);
		when(client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSLOT)).thenReturn(1);
		when(client.getVarcStrValue(330)).thenReturn("Alice");
		when(plugin.isDawnbringerBearer("Alice")).thenReturn(true);
		assertTrue(containsColor(render(), Color.MAGENTA));
		when(plugin.isDawnbringerBearer("Alice")).thenReturn(false);
		assertFalse(containsColor(render(), Color.MAGENTA));
	}

	@Test
	public void deadAndDisconnectedPlayersHaveNoDawnbringerFill()
	{
		when(plugin.shouldRender()).thenReturn(true);
		when(client.getVarcStrValue(330)).thenReturn("Alice");
		when(plugin.isDawnbringerBearer("Alice")).thenReturn(true);
		for (int health : new int[]{30, 31})
		{
			when(client.getVarbitValue(VarbitID.TOB_CLIENT_P0)).thenReturn(health);
			assertFalse(containsColor(render(), Color.MAGENTA));
		}
	}

	@Test
	public void healthPercentHandlesSentinelsAndClampsValues()
	{
		assertEquals(0, TobPlayer.healthPercent(0), 0);
		assertEquals(0, TobPlayer.healthPercent(1), 0);
		assertEquals(50, TobPlayer.healthPercent(14), 0);
		assertEquals(100, TobPlayer.healthPercent(27), 0);
		assertEquals(100, TobPlayer.healthPercent(28), 0);
		assertEquals(0, TobPlayer.healthPercent(30), 0);
		assertEquals(0, TobPlayer.healthPercent(31), 0);
	}

	private BufferedImage render()
	{
		BufferedImage image = new BufferedImage(250, 250, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			// PanelComponent computes its background size from the preceding frame.
			overlay.render(graphics);
			Dimension size = overlay.render(graphics);
			overlay.getBounds().setSize(size == null ? new Dimension() : size);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static boolean containsColor(BufferedImage image, Color color)
	{
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if (image.getRGB(x, y) == color.getRGB())
				{
					return true;
				}
			}
		}
		return false;
	}
}

package trevor.tobhealthbars;

import java.util.Arrays;
import java.util.Collections;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.kit.KitType;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class DawnbringerTrackerTest
{
	private final DawnbringerTracker tracker = new DawnbringerTracker();

	@Test
	public void highlightFollowsWeaponHandoffsAndClearsWhenUnequipped()
	{
		Player alice = player("Alice", true);
		Player bob = player("Bob", false);
		tracker.update(true, Arrays.asList(alice, bob));
		assertTrue(tracker.isBearer("Alice"));
		assertFalse(tracker.isBearer("Bob"));

		when(alice.getPlayerComposition().getEquipmentId(KitType.WEAPON)).thenReturn(-1);
		when(bob.getPlayerComposition().getEquipmentId(KitType.WEAPON)).thenReturn(ItemID.VERZIK_SPECIAL_WEAPON);
		tracker.update(true, Arrays.asList(alice, bob));
		assertFalse(tracker.isBearer("Alice"));
		assertTrue(tracker.isBearer("Bob"));

		when(bob.getPlayerComposition().getEquipmentId(KitType.WEAPON)).thenReturn(-1);
		tracker.update(true, Arrays.asList(alice, bob));
		assertFalse(tracker.isBearer("Bob"));
	}

	@Test
	public void comparesGameNamesWithoutMergingDifferentPlayers()
	{
		tracker.update(true, Collections.singletonList(player("A\u00a0B", true)));
		assertTrue(tracker.isBearer("<col=ffffff>a_b</col>"));
		assertTrue(tracker.isBearer("a-b"));
		assertFalse(tracker.isBearer("AB"));
		assertFalse(tracker.isBearer(null));
	}

	@Test
	public void roomExitDespawnAndResetClearStaleBearers()
	{
		Player alice = player("Alice", true);
		tracker.update(true, Collections.singletonList(alice));
		tracker.update(false, Collections.singletonList(alice));
		assertFalse(tracker.isBearer("Alice"));
		tracker.update(true, Collections.singletonList(alice));
		tracker.update(true, Collections.emptyList());
		assertFalse(tracker.isBearer("Alice"));
		tracker.update(true, Collections.singletonList(alice));
		tracker.clear();
		assertFalse(tracker.isBearer("Alice"));
	}

	@Test
	public void incompletePlayerDataIsSafe()
	{
		tracker.update(true, Arrays.asList(null, mock(Player.class), player(null, true), player("", true)));
		assertFalse(tracker.isBearer(""));
		tracker.update(true, null);
		assertFalse(tracker.isBearer("Alice"));
	}

	private static Player player(String name, boolean dawnbringer)
	{
		Player player = mock(Player.class);
		PlayerComposition composition = mock(PlayerComposition.class);
		when(player.getName()).thenReturn(name);
		when(player.getPlayerComposition()).thenReturn(composition);
		when(composition.getEquipmentId(KitType.WEAPON)).thenReturn(dawnbringer ? ItemID.VERZIK_SPECIAL_WEAPON : -1);
		return player;
	}
}

