package trevor.tobhealthbars;

import java.util.IdentityHashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;

/** Hides the party orbs while retaining the game's native spectator exit control. */
final class PartyOrbWidgets
{
	private final Client client;
	private final Map<Widget, Boolean> hiddenOrbs = new IdentityHashMap<>();
	private Widget statusContainer;
	private NativeLayout nativeLayout;

	@Inject
	PartyOrbWidgets(Client client)
	{
		this.client = client;
	}

	boolean isHudVisible()
	{
		Widget status = client.getWidget(InterfaceID.TobHud.STATUS_CONTAINER);
		return status != null && !status.isHidden();
	}

	void hideOrbs()
	{
		Widget status = client.getWidget(InterfaceID.TobHud.STATUS_CONTAINER);
		if (status != statusContainer)
		{
			restore();
			statusContainer = status;
		}
		if (status == null || status.isHidden())
		{
			restoreLayout();
			return;
		}
		for (TobPlayer player : TobPlayer.values())
		{
			Widget orb = client.getWidget(player.orbWidgetId);
			if (orb != null)
			{
				hiddenOrbs.putIfAbsent(orb, orb.isSelfHidden());
				orb.setHidden(true);
			}
		}
		// Never hide STATUS_CONTAINER or SPECTATOR_CONTAINER: the native exit stays usable.
		compactLayout(status);
	}

	void restore()
	{
		restoreLayout();
		hiddenOrbs.forEach(Widget::setHidden);
		hiddenOrbs.clear();
		statusContainer = null;
	}

	private void compactLayout(Widget status)
	{
		Widget spectator = client.getWidget(InterfaceID.TobHud.SPECTATOR_CONTAINER);
		if (nativeLayout == null || nativeLayout.status != status || nativeLayout.spectator != spectator)
		{
			restoreLayout();
			nativeLayout = new NativeLayout(status, spectator);
		}

		boolean showExit = spectator != null && !spectator.isHidden();
		// WidgetOverlay reserves the parent's dimensions, regardless of hidden children.
		// Both dimensions must be zero to avoid advancing RuneLite's overlay anchor.
		int width = showExit ? spectator.getWidth() : 0;
		int height = showExit ? spectator.getHeight() : 0;
		status.setOriginalWidth(width);
		status.setOriginalHeight(height);
		status.setWidthMode(WidgetSizeMode.ABSOLUTE);
		status.setHeightMode(WidgetSizeMode.ABSOLUTE);
		if (spectator != null)
		{
			spectator.setOriginalX(0);
			spectator.setOriginalY(0);
			spectator.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
			spectator.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		}
		status.revalidateScroll();
	}

	void restoreLayout()
	{
		if (nativeLayout != null)
		{
			nativeLayout.restore();
			nativeLayout = null;
		}
	}

	/** Restore before native HUD scripts run, then capture their new layout afterwards. */
	private static final class NativeLayout
	{
		private final Widget status;
		private final Widget spectator;
		private final int width;
		private final int height;
		private final int widthMode;
		private final int heightMode;
		private final int spectatorX;
		private final int spectatorY;
		private final int spectatorXMode;
		private final int spectatorYMode;

		private NativeLayout(Widget status, Widget spectator)
		{
			this.status = status;
			this.spectator = spectator;
			width = status.getOriginalWidth();
			height = status.getOriginalHeight();
			widthMode = status.getWidthMode();
			heightMode = status.getHeightMode();
			spectatorX = spectator == null ? 0 : spectator.getOriginalX();
			spectatorY = spectator == null ? 0 : spectator.getOriginalY();
			spectatorXMode = spectator == null ? 0 : spectator.getXPositionMode();
			spectatorYMode = spectator == null ? 0 : spectator.getYPositionMode();
		}

		private void restore()
		{
			status.setOriginalWidth(width);
			status.setOriginalHeight(height);
			status.setWidthMode(widthMode);
			status.setHeightMode(heightMode);
			if (spectator != null)
			{
				spectator.setOriginalX(spectatorX);
				spectator.setOriginalY(spectatorY);
				spectator.setXPositionMode(spectatorXMode);
				spectator.setYPositionMode(spectatorYMode);
			}
			status.revalidateScroll();
		}
	}
}

package trevor.tobhealthbars;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.Text;

public class TobHealthBarsOverlay extends Overlay
{
	static final Color HP_GREEN = new Color(0, 146, 54, 230);
	private static final Color HP_RED = new Color(102, 15, 16, 230);
	private final Client client;
	private final TobHealthBarsPlugin plugin;
	private final TobHealthBarsConfig config;
	private final PanelComponent panel = new PanelComponent();

	@Inject
	TobHealthBarsOverlay(Client client, TobHealthBarsPlugin plugin, TobHealthBarsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(OverlayPriority.HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		clearRows();
		panel.getChildren().clear();
		if (!plugin.shouldRender())
		{
			return null;
		}

		int localIndex = client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSLOT) - 1;
		for (TobPlayer player : TobPlayer.values())
		{
			int health = client.getVarbitValue(player.healthVarbit);
			if (health == 0)
			{
				continue;
			}
			String name = client.getVarcStrValue(player.nameVarc);
			String label = name == null || name.isEmpty() ? "-" : Text.removeTags(name);
			if (player.ordinal() == localIndex && !config.showLocalName())
			{
				label = "Me";
			}
			TitleComponent title = TitleComponent.builder().text(label).build();
			ProgressBarComponent bar = new ProgressBarComponent();
			bar.setBackgroundColor(HP_RED);
			bar.setForegroundColor(health < 30 && plugin.isDawnbringerBearer(name) ? config.dawnbringerColor() : HP_GREEN);
			bar.setValue(TobPlayer.healthPercent(health));
			panel.getChildren().add(title);
			panel.getChildren().add(bar);
		}

		return panel.render(graphics);
	}

	void clearRows()
	{
		panel.getChildren().clear();
	}
}

package trevor.tobhealthbars;

import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;

enum TobPlayer
{
	PLAYER_1(VarbitID.TOB_CLIENT_P0, 330, InterfaceID.TobHud._0_CONTAINER),
	PLAYER_2(VarbitID.TOB_CLIENT_P1, 331, InterfaceID.TobHud._1_CONTAINER),
	PLAYER_3(VarbitID.TOB_CLIENT_P2, 332, InterfaceID.TobHud._2_CONTAINER),
	PLAYER_4(VarbitID.TOB_CLIENT_P3, 333, InterfaceID.TobHud._3_CONTAINER),
	PLAYER_5(VarbitID.TOB_CLIENT_P4, 334, InterfaceID.TobHud._4_CONTAINER);

	// 0 = absent, 1..27 = 0..100%, 30 = dead, 31 = disconnected.
	final int healthVarbit;
	final int nameVarc;
	final int orbWidgetId;

	TobPlayer(int healthVarbit, int nameVarc, int orbWidgetId)
	{
		this.healthVarbit = healthVarbit;
		this.nameVarc = nameVarc;
		this.orbWidgetId = orbWidgetId;
	}

	static double healthPercent(int health)
	{
		return health == 30 || health == 31 ? 0 : Math.max(0, Math.min(100, (health - 1) * 100.0 / 26));
	}
}

package trevor.tobhealthbars;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "ToB Health Bars Enhanced",
	description = "ToB health bars with spectator exit support and Dawnbringer highlighting",
	tags = {"tob", "theatre", "verzik", "dawnbringer", "spectator"}
)
public class TobHealthBarsPlugin extends Plugin
{
	private static final int VERZIK_REGION = 12611;

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private TobHealthBarsOverlay overlay;
	@Inject
	private PartyOrbWidgets partyOrbs;
	@Inject
	private TobHealthBarsConfig config;

	private final DawnbringerTracker dawnbringer = new DawnbringerTracker();
	private boolean inTob;
	private boolean running;

	@Override
	protected void startUp()
	{
		running = true;
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			if (running)
			{
				refreshState();
				updateDawnbringer();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		inTob = false;
		dawnbringer.clear();
		overlay.clearRows();
		overlayManager.remove(overlay);
		clientThread.invoke(partyOrbs::restore);
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		refreshState();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		refreshState();
		updateDawnbringer();
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (isHudScript(event.getScriptId()))
		{
			partyOrbs.restoreLayout();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (isHudScript(event.getScriptId()))
		{
			refreshState();
		}
	}

	private static boolean isHudScript(int scriptId)
	{
		return scriptId == 2087 || scriptId == 2296 || scriptId == 2509;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			inTob = false;
			dawnbringer.clear();
			overlay.clearRows();
			partyOrbs.restore();
		}
		else
		{
			refreshState();
			updateDawnbringer();
		}
	}

	private void refreshState()
	{
		inTob = client.getGameState() == GameState.LOGGED_IN
			&& client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS) > 1;
		if (inTob)
		{
			partyOrbs.hideOrbs();
		}
		else
		{
			partyOrbs.restore();
			dawnbringer.clear();
			overlay.clearRows();
		}
	}

	private void updateDawnbringer()
	{
		Player local = client.getLocalPlayer();
		WorldView world = client.getTopLevelWorldView();
		boolean inVerzik = inTob && config.highlightDawnbringer() && local != null && world != null
			&& WorldPoint.fromLocalInstance(client, local.getLocalLocation()).getRegionID() == VERZIK_REGION;
		dawnbringer.update(inVerzik, inVerzik ? world.players() : null);
	}

	boolean shouldRender()
	{
		return inTob && client.getGameState() == GameState.LOGGED_IN && partyOrbs.isHudVisible();
	}

	boolean isDawnbringerBearer(String name)
	{
		return config.highlightDawnbringer() && dawnbringer.isBearer(name);
	}

	@Provides
	TobHealthBarsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TobHealthBarsConfig.class);
	}
}

package trevor.tobhealthbars;

import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.kit.KitType;
import net.runelite.client.util.Text;

/**
 * Uses TobUtilities' visible-player weapon-slot approach; see LICENSE-TobUtilities.
 */
final class DawnbringerTracker
{
	private final Set<String> bearers = new HashSet<>();

	void update(boolean inVerzik, Iterable<? extends Player> players)
	{
		clear();
		if (!inVerzik || players == null)
		{
			return;
		}

		for (Player player : players)
		{
			if (player == null || player.getName() == null)
			{
				continue;
			}
			PlayerComposition composition = player.getPlayerComposition();
			if (composition != null && composition.getEquipmentId(KitType.WEAPON) == ItemID.VERZIK_SPECIAL_WEAPON)
			{
				String name = normalize(player.getName());
				if (!name.isEmpty())
				{
					bearers.add(name);
				}
			}
		}
	}

	boolean isBearer(String name)
	{
		return name != null && bearers.contains(normalize(name));
	}

	void clear()
	{
		bearers.clear();
	}

	private static String normalize(String name)
	{
		// Preserve word boundaries
		return Text.toJagexName(Text.removeTags(name)).toLowerCase(Locale.ROOT);
	}
}

